function V080_merchPhoto(id,look=0){const safe=Number.isInteger(look)&&look>=0&&look<V080_merchLooks.length?look:0,panel=safe%3;return `<div class="merch-photo merch-edition-${safe}" role="img" aria-label="${esc(merchItems.find(m=>m[0]===id)?.[1]||'Merchandise')}: ${V080_merchLooks[safe]}" style="background-image:url('${MERCH_ART[id]||''}');background-position:${panel*50}% center"></div>`}
