function V080_personPhoto(key,name,large=false){let h=2166136261;for(const c of String(key))h=Math.imul(h^c.charCodeAt(0),16777619)>>>0;const skin=['#5b3527','#754734','#925c42','#b97958','#d19a73','#e4b990','#8d5a45','#c98b68'][h%8],hair=['#151218','#2a1a16','#3a2820','#5d3a24','#10151c','#6a4a2c'][Math.floor(h/8)%6],shirt=['#264653','#5b2a50','#33415c','#7a4b2f','#1f4d3b','#493657','#2f4858','#673c4f'][Math.floor(h/48)%8],bg=['#d7b56d','#8fb8b2','#b894c4','#a4b7d3','#d49b82','#87a57a','#c5a27a','#7aa7bd'][Math.floor(h/384)%8],hairStyle=Math.floor(h/3072)%5,earring=Math.floor(h/15360)%3===0;const hairPath=[`<path d="M22 39q2-25 28-25t28 25q-8-13-28-13T22 39" fill="${hair}"/>`,`<path d="M20 42q0-30 30-30t30 30q-4-8-10-13-2 12-20 12t-20-12q-7 5-10 13" fill="${hair}"/>`,`<path d="M24 36q8-25 26-25 24 0 30 28-9-8-16-9-2 9-14 9-14 0-18-10-5 2-8 7" fill="${hair}"/>`,`<path d="M22 41q2-25 28-25 9 0 18 5l7 18-13-7-11 5-12-6-17 10" fill="${hair}"/>`,`<path d="M25 34q4-22 25-22t26 24l-10-9-13 3-10-4-18 8" fill="${hair}"/>`][hairStyle];const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="16" fill="${bg}"/><circle cx="50" cy="42" r="24" fill="${skin}"/>${hairPath}<path d="M20 100q3-31 30-31t30 31" fill="${shirt}"/><circle cx="42" cy="43" r="2" fill="#151515"/><circle cx="58" cy="43" r="2" fill="#151515"/><path d="M45 55q5 4 10 0" fill="none" stroke="#5a2f2f" stroke-width="2" stroke-linecap="round"/>${earring?'<circle cx="75" cy="50" r="2" fill="#f5df9a"/>':''}<path d="M10 83h80" stroke="rgba(255,255,255,.22)"/></svg>`;return `<span class="person-photo v080-person ${large?'portrait-large':''}" role="img" aria-label="Stylized fictional portrait of ${esc(name)}" style="background-image:url(&quot;data:image/svg+xml,${encodeURIComponent(svg)}&quot;)"></span>`}
personPhoto=V080_personPhoto;

function V080_validatePresentationState(){if(s.onboarding&&(s.onboarding.version!==1||typeof s.onboarding.seen!=='boolean'))throw Error('Invalid onboarding');if(s.collection&&(!Array.isArray(s.collection.purchased)||s.collection.purchased.length>120||new Set(s.collection.purchased).size!==s.collection.purchased.length||s.collection.purchased.some(id=>typeof id!=='string'||!/^\d+-[0-5]$/.test(id))))throw Error('Invalid collection');for(const m of s.empire.merch)if(m.look!==undefined&&(!Number.isInteger(m.look)||m.look<0||m.look>=V080_merchLooks.length))throw Error('Invalid merchandise artwork');for(const a of s.empire.assets)if(a.editionId!==undefined&&(typeof a.editionId!=='string'||!/^\d+-[0-5]$/.test(a.editionId)||typeof a.edition!=='string'))throw Error('Invalid edition');if(s.v080){if(s.v080.version!==V080_SCHEMA||!Array.isArray(s.v080.commercial?.offers)||!Array.isArray(s.v080.catalog?.holdings))throw Error('Invalid 0.8 state');for(const h of s.v080.catalog.holdings)if(!Number.isInteger(h.id)||!Number.isInteger(h.artist)||!Number.isFinite(h.share)||h.share<=0||h.share>1||!Number.isFinite(h.basis)||h.basis<0)throw Error('Invalid catalog holding')}}
validatePresentationState=V080_validatePresentationState;

