const V080_reviewArtistOffer071=reviewArtistOffer;
reviewArtistOffer=function(id){const o=s.labelBusiness?.offers?.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(o)V080_markReviewed(o);return V080_reviewArtistOffer071(id)};
const V080_counterArtistOffer071=counterArtistOffer;
counterArtistOffer=function(e,id){const result=V080_counterArtistOffer071(e,id),o=s.labelBusiness?.offers?.find(x=>x.id===id&&!x.used);if(o)V080_extendOffer(o);return result};
const V080_labelPage071=labelPage;
labelPage=function(){return V080_labelPage071().replace(/Expires after Week 9007199254740991/g,'No deadline until reviewed')};

const V080_createOpportunity071=createOpportunity;
createOpportunity=function(){const before=s.expansion.opportunities.length;V080_createOpportunity071();if(s.expansion.opportunities.length>before){const o=s.expansion.opportunities.at(-1);o.reviewedMonth=null;o.originalExpiry=o.expires;o.expires=Number.MAX_SAFE_INTEGER}};
const V080_acceptOpportunity071=acceptOpportunity;
acceptOpportunity=function(id,confirmed=false){const o=s.expansion.opportunities.find(x=>x.id===id&&!x.done&&x.expires>=s.week);if(o)V080_markReviewed(o);return V080_acceptOpportunity071(id,confirmed)};
function V080_opportunitiesPage(){const list=s.expansion.opportunities.filter(x=>!x.done&&x.expires>=s.week);return head('Appearances, features and opening doors','Career opportunities.')+`<p>Unreviewed opportunities stay open. Once reviewed, you receive a full decision window.</p>${list.map(o=>`<section class="card"><span class="eyebrow">${esc(V080_offerDeadlineText(o))}</span><h2>${esc(o.type)}</h2><p>With ${esc(o.name)} · ${money(o.fee)} · 15 energy.</p><button class="primary" onclick="V080_markReviewed(s.expansion.opportunities.find(x=>x.id==='${o.id}'));acceptOpportunity('${o.id}')">Review offer</button><button class="secondary" onclick="declineOpportunity('${o.id}')">Decline</button></section>`).join('')||'<section class="card"><p>No active career opportunities.</p></section>'}`}
opportunitiesPage=V080_opportunitiesPage;

const V080_reviewMedia071=reviewMedia;
reviewMedia=function(id){const o=s.empire.media.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(o)V080_markReviewed(o);return V080_reviewMedia071(id)};
const V080_counterMedia071=counterMedia;
counterMedia=function(e,id){const r=V080_counterMedia071(e,id),o=s.empire.media.find(x=>x.id===id&&!x.used);if(o)V080_extendOffer(o);return r};
settleCommerce=function(){const active=s.empire.merch.filter(m=>m.stock>0);for(const m of active){const spec=merchItems.find(x=>x[0]===m.item),demand=Math.max(0,Math.floor(s.fans*.015/Math.max(1,active.length)*Math.pow(spec[3]/m.price,2)*rand(.6,1.3))),sold=Math.min(m.stock,demand),gross=cents(sold*m.price);m.stock-=sold;m.sold+=sold;changeCash(gross);recordIncome('live',gross);if(sold)moneyEvent(m.name+' sales',gross)}s.empire.media=s.empire.media.filter(o=>!o.used&&o.expires>=s.week).slice(-20)};

const V080_settleAssets071=settleAssets;
settleAssets=function(){const r=V080_settleAssets071();settleCommercialContracts080();settleCatalogHoldings080();return r};

artistLabelCut=function(royalties){const c=s.expansion.contract,w=s.finance.week;if(!c)return 0;const music=(c.catalogReleased?0:royalties+(['record','distribution','360'].includes(c.type)?w.albumSales||0:0)),other=c.type==='360'?(w.live||0)+(w.media||0):0;return cents((music+other)*c.share)};
closeFinances=function(royalties,rate){const f=s.finance,w=f.week,labelCut=artistLabelCut(royalties),labelBusiness=w.labelBusiness||0,labelPayroll=w.labelPayroll||0,albumSales=w.albumSales||0,investment=w.investment||0,media=w.media||0,agentFee=agentCommission(royalties+w.live+albumSales+media),overhead=cents((royalties+w.live+albumSales)*rate+media*rate*.35),revenue=cents(royalties+w.live+w.wages+albumSales+labelBusiness+investment+media),expenses=cents(w.expenses+overhead+labelCut+agentFee);if(s.expansion.contract)s.expansion.contract.recovered=(s.expansion.contract.recovered||0)+labelCut;f.weeks++;f.revenue=cents(f.revenue+revenue);f.expenses=cents(f.expenses+expenses);const profit=cents(f.revenue-f.expenses),yearEnd=s.week%52===0,target=yearEnd?taxDue(profit):cents(taxDue(Math.max(0,profit)*52/f.weeks)*f.weeks/52),reserveChange=cents(target-f.reserve);f.reserve=target;changeCash(royalties-overhead-reserveChange-labelCut-agentFee);const report={week:s.week,revenue,investment,media,agentFee,royalties,albumSales,labelBusiness,labelPayroll,labelCut,wages:w.wages,live:w.live,expenses,actionExpenses:w.expenses,overhead,rate,taxReserve:reserveChange,net:cents(revenue-expenses-reserveChange),cash:s.cash,yearEnd,settlement:yearEnd?target:0};if(yearEnd){f.lastSettlement={year:f.year,profit,tax:target,reconciliation:reserveChange};f.taxesPaid=cents(f.taxesPaid+target);f.reserve=0;f.year++;f.weeks=0;f.revenue=0;f.expenses=0}f.week={wages:0,live:0,expenses:0};f.last=report;return report};
financeRows=function(r,full=false){const payout=cents(r.royalties+(r.albumSales||0)+(r.labelBusiness||0)-(r.labelPayroll||0)-(r.labelCut||0)-r.overhead-r.taxReserve);return [...(full?[['Taxable revenue including realized investments',money(r.revenue)],['Commercial / media income',money(r.media||0)],['Investment gains, distributions & rent',money(r.investment||0)],['Work, advances & live income',money(r.wages+r.live)],['Action costs','−'+money(r.actionExpenses-(r.labelPayroll||0))]]:[]),['Streaming royalties',money(r.royalties)],['Album downloads',money(r.albumSales||0)],['Label-business receipts',money(r.labelBusiness||0)],['Label payroll','−'+money(r.labelPayroll||0)],['Your label / 360 contract share','−'+money(r.labelCut||0)],['Career overhead','−'+money(r.overhead)],[r.taxReserve<0?'Tax reserve returned':'Tax reserve set aside',(r.taxReserve<0?'+':'−')+money(Math.abs(r.taxReserve))],[full?'Net for the whole week':'Week-close payout',money(full?r.net:payout)],['Spendable cash',money(r.cash)]]};

const V080_advance071=advance;
advance=function(confirmed=false){if(!confirmed){const weeks=monthLength(),risk=V080_offerRiskCount(weeks);modal(`<h2>Close this month?</h2><p>${weeks} chart weeks will resolve. Your unused ${s.energy}/200 energy will be replaced by 200. Music, contracts, income taxes, staff, investments, catalog holdings and rentals settle during this advance.</p><p><strong>${risk?risk+' reviewed offer'+(risk===1?'':'s')+' may expire during this advance.':'No reviewed offer is currently at risk of expiring.'}</strong> Unreviewed offers are protected until you open them.</p><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="$('modal').close();advance(true)">Advance week</button>`);return}return V080_advance071(true)};

const V080_monthlyRecap071=monthlyRecap;
monthlyRecap=function(report){generateCommercialOffers080();queueSave();const unread=V080_unreadCount(),openOffers=(s.labelBusiness.offers||[]).filter(o=>!o.used&&o.expires>=s.week).length+s.v080.commercial.offers.filter(o=>o.status==='open'&&o.expires>=s.week).length;const index=report.monthIndex??Math.max(0,s.empire.month-1);modal(`<article class="month-issue"><div class="issue-masthead"><strong>ENCORE</strong><span>CAREER REPORT<br>${careerDate(index)}</span></div><div class="issue-hero"><img src="${ENCORE_ART.backstage}" alt=""><div><span>${esc(s.name)}</span><h2>${report.streams?'YOUR MONTH.<br>YOUR MOMENT.':'THE NEXT<br>CHAPTER.'}</h2></div></div><div class="issue-numbers"><div><strong>${compact(report.streams)}</strong><span>Streams</span></div><div><strong>${report.fans>=0?'+':''}${compact(report.fans)}</strong><span>Net fans</span></div><div><strong>${money(report.royalties)}</strong><span>Royalties</span></div></div><div class="issue-ledger">${profileRows([['Cash movement',money(report.cashChange)],['Tax reserve change',money(report.taxes)],['Spendable cash',money(s.cash)],['Open offers',String(openOffers)],['Unread inbox',String(unread)]])}<p>Includes assets, staff, rentals, commercial installments and catalog distributions. Chart weeks ${report.start}–${report.end} resolved.</p></div><div class="issue-actions"><button class="primary" onclick="$('modal').close()">Continue · ${careerDate()}</button><button class="secondary" onclick="$('modal').close();openDestination('Inbox')">Open Inbox${unread?' · '+unread+' new':''} →</button><button class="secondary" onclick="$('modal').close();openDestination('Offers')">Review offers →</button></div></article>`,'month-dialog')};

function V080_career(){migrateV080();const nav=careerMenu();const extra={Market:marketPage,Location:locationPage,Agency:agencyPage,League:labelLeaguePage,Social:pulsePage,Deals:dealsPage,Wealth:wealthPage,Properties:propertiesPage,Team:teamPage,Commerce:commercePage,Touring:tourPage,Campaigns:marketingPage,Opportunities:opportunitiesPage,Labels:labelPage,Legacy:V080_awardsPage,Awards:V080_awardsPage,Milestones:V080_milestonesPage,Celebrations:V080_celebrationsPage,Inbox:V080_inboxPage,Offers:V080_offersPage,CatalogMarket:V080_catalogMarketPage,Saves:savesPage};if(extra[careerTab])return nav+extra[careerTab]();if(careerTab==='Achievements')return nav+achievementsPage();if(careerTab==='Certifications')return nav+certificationsPage();if(careerTab==='Finances')return nav+financeScreen();if(careerTab==='Releases')return nav+catalog();if(careerTab==='Activity')return nav+head('Your career, week by week','Activity.')+`<section class="card">${s.history.map(x=>`<div class="story"><small>WEEK ${x.week}</small>${esc(x.text)}</div>`).join('')}</section>`;return nav+careerProfile()}
career=V080_career;

